// Keeps one source of truth for the role agents.
//   .claude/agents/<name>.md   written by hand (Claude Code format)
//   .opencode/agents/<name>.md generated here (OpenCode format), never edited
//
//   npm run ai:sync    regenerate
//   npm run ai:check   fail if the generated files are stale (used by verify and CI)
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { REPO_ROOT } from './guards/index.mjs';

const SOURCE = join(REPO_ROOT, '.claude', 'agents');
const TARGET = join(REPO_ROOT, '.opencode', 'agents');
const check = process.argv.includes('--check');

/** Parses the simple `key: value` frontmatter these agent files use. */
function parseAgent(text, file) {
  const match = /^---\r?\n([\s\S]*?)\r?\n---\r?\n([\s\S]*)$/.exec(text);
  if (!match) throw new Error(`${file}: missing frontmatter`);
  const meta = {};
  for (const line of match[1].split(/\r?\n/)) {
    const separator = line.indexOf(':');
    if (separator > 0) meta[line.slice(0, separator).trim()] = line.slice(separator + 1).trim();
  }
  for (const key of ['name', 'description', 'tools']) {
    if (!meta[key]) throw new Error(`${file}: frontmatter needs "${key}"`);
  }
  return { meta, body: match[2].replace(/\r\n/g, '\n').trimStart() };
}

function toOpenCode({ meta, body }, file) {
  const tools = new Set(meta.tools.split(',').map((tool) => tool.trim()));
  const canEdit = tools.has('Edit') || tools.has('Write');
  const canRunCommands = tools.has('Bash') || tools.has('PowerShell');
  const canBrowse = tools.has('WebFetch') || tools.has('WebSearch');

  const permission = [
    // An agent without edit tools in Claude Code is read-only in OpenCode too.
    ...(canEdit ? [] : ['  edit: deny']),
    ...(canRunCommands ? [] : ['  bash: deny']),
    ...(canBrowse ? [] : ['  webfetch: deny']),
  ];

  return [
    '---',
    `description: ${JSON.stringify(meta.description)}`,
    'mode: subagent',
    ...(permission.length > 0 ? ['permission:', ...permission] : []),
    '---',
    '',
    `<!-- GENERATED from .claude/agents/${file} by \`npm run ai:sync\`. Do not edit this file. -->`,
    '',
    body.trimEnd(),
    '',
  ].join('\n');
}

const sources = readdirSync(SOURCE).filter((file) => file.endsWith('.md'));
const expected = new Map(
  sources.map((file) => [
    file,
    toOpenCode(parseAgent(readFileSync(join(SOURCE, file), 'utf8'), file), file),
  ]),
);
const existing = existsSync(TARGET)
  ? readdirSync(TARGET).filter((file) => file.endsWith('.md'))
  : [];

if (check) {
  const problems = [
    ...[...expected.keys()].filter(
      (file) =>
        !existing.includes(file) ||
        readFileSync(join(TARGET, file), 'utf8').replace(/\r\n/g, '\n') !== expected.get(file),
    ),
    ...existing.filter((file) => !expected.has(file)).map((file) => `${file} (no source)`),
  ];
  if (problems.length > 0) {
    process.stderr.write(
      `OpenCode agents are out of date: ${problems.join(', ')}.\nRun \`npm run ai:sync\` and commit the result.\n`,
    );
    process.exit(1);
  }
  process.stdout.write(`OpenCode agents are in sync (${expected.size} agents).\n`);
} else {
  mkdirSync(TARGET, { recursive: true });
  for (const file of existing) if (!expected.has(file)) rmSync(join(TARGET, file));
  for (const [file, content] of expected) writeFileSync(join(TARGET, file), content);
  process.stdout.write(`Generated ${expected.size} OpenCode agents in .opencode/agents/.\n`);
}
